import threading as t
import time
from cachetools import cached, cachedmethod, LRUCache
from cachetools import func

def parallel(f, n=12):
    start = t.Barrier(n)
    results, errors = [], []
    def run():
        try:
            start.wait(2)
            results.append(f())
        except BaseException as e:
            errors.append(e)
    threads = [t.Thread(target=run, daemon=True) for _ in range(n)]
    for th in threads: th.start()
    for th in threads: th.join(3)
    assert not any(th.is_alive() for th in threads), 'deadlock'
    return results, errors

for info in (False, True):
    for separate_lock in (False, True):
        mutex = t.RLock()
        cond = t.Condition(mutex)
        calls = []
        @cached({}, condition=cond, lock=mutex if separate_lock else None, info=info)
        def f(k):
            calls.append(k)
            time.sleep(.03)
            return k * 2
        values, errors = parallel(lambda: f(3))
        assert not errors and values == [6]*12 and calls == [3]
        assert f.cache_condition is cond
        if info: assert f.cache_info()[:2] == (11, 1)
        f.cache_clear()
        assert not f.cache

for name in func.__all__:
    calls = []
    @getattr(func, name)()
    def f(k):
        calls.append(k)
        time.sleep(.03)
        return k
    assert isinstance(f.cache_condition, t.Condition)
    assert parallel(lambda: f(7)) == ([7]*12, [])
    assert calls == [7]

for direct in (False, True):
    cond = t.Condition()
    class C:
        __hash__ = None
        def __init__(self):
            self.cache, self.cond, self.calls = {}, cond, 0
        @cachedmethod(lambda self: self.cache,
                      condition=cond if direct else lambda self: self.cond)
        def f(self, k):
            self.calls += 1
            time.sleep(.03)
            return k
    c = C()
    assert parallel(lambda: c.f(4)) == ([4]*12, [])
    assert c.calls == 1
    c.f.cache_clear(c)
    assert not c.cache

# Exceptions and rejected values must release pending keys and wake waiters.
for cache in ({}, LRUCache(0)):
    calls = []
    @cached(cache, condition=t.Condition(), info=True)
    def f(k):
        calls.append(k)
        time.sleep(.002)
        if len(calls) == 1: raise RuntimeError('first attempt')
        return k
    values, errors = parallel(lambda: f(5))
    assert values == [5]*11 and len(errors) == 1
    assert isinstance(errors[0], RuntimeError)
    assert len(calls) == (12 if cache.maxsize == 0 else 2) if isinstance(cache, LRUCache) else len(calls) == 2

# Different keys must run concurrently, and recursive calls for different keys work.
barrier = t.Barrier(2)
@cached({}, condition=t.Condition())
def f(k):
    barrier.wait(2)
    return k
counter = iter(range(2))
values, errors = parallel(lambda: f(next(counter)), n=2)
assert not errors and sorted(values) == [0, 1]
@cached({}, condition=t.Condition())
def fib(n):
    return n if n < 2 else fib(n-1) + fib(n-2)
assert fib(12) == 144
import cachetools
assert not hasattr(cachetools, 'MRUCache') and not hasattr(func, 'mru_cache')
print('Concurrency and removal checks passed')
